const year = new Date().getFullYear();
// Find the 4th Thursday of November
let nov1 = new Date(year, 10, 1); // Month is 0-indexed
let dayOfWeek = nov1.getDay(); // 0=Sun
let firstThursday = 1 + ((4 - dayOfWeek + 7) % 7);
let fourthThursday = firstThursday + 21;
let thanksgiving = new Date(year, 10, fourthThursday);
console.log('Thanksgiving ' + year + ': ' + thanksgiving.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }));
"

