const ts = 1788269400;
const d = new Date(ts * 1000);
console.log('UTC:', d.toISOString());
console.log('UTC time:', d.toLocaleString('en-US', { timeZone: 'UTC', hour: '2-digit', minute: '2-digit', hour12: true }));
console.log();

const zones = [
  'America/New_York',    // EST/EDT -5/-4
  'America/Chicago',     // CST/CDT -6/-5
  'America/Denver',      // MST/MDT -7/-6
  'America/Los_Angeles', // PST/PDT -8/-7
  'America/Phoenix',     // MST (no DST) -7
];

for (const tz of zones) {
  const local = d.toLocaleString('en-US', { timeZone: tz, weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true, timeZoneName: 'short' });
  console.log(tz + ': ' + local);
}
"

